/**
 * A planet's atmosphere, drawn — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of `ShaderMaterial` for
 * the planet's sky, loaded only by dynamic `import()` from the planet view,
 * so a world that is not a planet never fetches it.
 *
 * A sphere the size of the air's top, around the planet's centre, drawn from
 * inside (its far side), so the sky fills the view from the ground and the
 * air's edge glows around the planet from space. The sunlight the air
 * scatters toward the eye is summed along each ray as the processor's
 * reference does (atmosphere.ts): the same constants, the same steps. The
 * sums are made each frame for a small picture of the sky around the eye
 * (skyView.ts), which the sphere looks up for each pixel; where the graphics
 * card cannot draw that picture in floating point, the sphere sums them for
 * each pixel itself. The sphere is drawn after the ground and does not write
 * depth, so no pixel the ground hides pays for it. A sun disc, dimmed by the
 * air in front of it, and stars where the sky is dark.
 *
 * As skyChunk.ts does, the shader is written in WGSL for WebGPU and GLSL for
 * WebGL2, chosen by engine kind, so no GLSL-to-WGSL translator is fetched.
 * The two are kept in step: the same inputs, the same sums.
 */
import { ShaderMaterial } from '@babylonjs/core/Materials/shaderMaterial';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ProceduralTexture } from '@babylonjs/core/Materials/Textures/Procedurals/proceduralTexture';
import { Texture } from '@babylonjs/core/Materials/Textures/texture';
import { Constants } from '@babylonjs/core/Engines/constants';
import { CreateSphere } from '@babylonjs/core/Meshes/Builders/sphereBuilder';
import { Mesh } from '@babylonjs/core/Meshes/mesh';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import { Matrix, Vector3 } from '@babylonjs/core/Maths/math.vector';
import type { Scene } from '@babylonjs/core/scene';
import type { Atmosphere } from './atmosphere';
import type { StarFieldHandle, AirShellHandle, AirVeilFrame, AirVeilHandle, AtmosphereHandle } from './planetView';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import type { UniformBuffer } from '@babylonjs/core/Materials/uniformBuffer';
import { NOISE_GLSL, NOISE_WGSL } from './cloudNoiseSource';
import { SKY_VIEW_BEARINGS, SKY_VIEW_HEIGHT, SKY_VIEW_WIDTH, skyViewFrame } from './skyView';
import { materialArrivals } from './materialArrivals';
import { isAway, takePlugin } from './awayMaterials';

/** The air's own numbers, which the sums take. */
const AIR_UNIFORMS = ['radius', 'top', 'rayleighHeight', 'mieHeight', 'rayleigh', 'mie', 'steps', 'lightSteps'] as const;
/** The eye's frame for the sky's picture (skyView.ts `SkyViewFrame`). */
const VIEW_FRAME_UNIFORMS = ['viewUp', 'viewForward', 'viewSide', 'viewHorizon', 'viewBelow'] as const;

/** Every input the sphere's shader takes, in both languages, whether it looks the sky up or sums it. */
export const ATMOSPHERE_UNIFORMS = [
  'world',
  'worldViewProjection',
  'eye',
  'centre',
  'sunDirection',
  ...AIR_UNIFORMS,
  ...VIEW_FRAME_UNIFORMS,
  'toStars',
  'starDensity',
  'starSeed',
  'time',
  'airStrength',
] as const;

/** Every input the sky's picture takes. */
export const SKY_VIEW_UNIFORMS = ['eye', 'centre', 'sunDirection', ...AIR_UNIFORMS, ...VIEW_FRAME_UNIFORMS] as const;

/** The most samples along a ray either shader takes; `steps` and `lightSteps` choose fewer. */
const MAX_STEPS = 32;
const MAX_LIGHT_STEPS = 8;

/** A number as a shader's float literal. */
const f = (n: number) => (Number.isInteger(n) ? `${n}.0` : String(n));

// ---- GLSL (WebGL2) ----
const AIR_DECLARATIONS_GLSL = `
uniform vec3 eye;
uniform vec3 centre;
uniform vec3 sunDirection;
uniform float radius;
uniform float top;
uniform float rayleighHeight;
uniform float mieHeight;
uniform vec3 rayleigh;
uniform float mie;
uniform float steps;
uniform float lightSteps;
uniform vec3 viewUp;
uniform vec3 viewForward;
uniform vec3 viewSide;
uniform float viewHorizon;
uniform float viewBelow;
`;

const AIR_GLSL = `
vec2 sphereHit(vec3 o, vec3 d, float r) {
  float b = dot(o, d);
  float c = dot(o, o) - r * r;
  float disc = b * b - c;
  if (disc < 0.0) return vec2(1e20, -1e20);
  float s = sqrt(disc);
  return vec2(-b - s, -b + s);
}
// The light the air scatters toward the eye at o (from the planet's centre) along d, untone-mapped; in through, the share of space's light it lets through.
vec3 airLight(vec3 o, vec3 d, vec3 sun, out vec3 through) {
  float outer = radius + top;
  vec3 sumR = vec3(0.0);
  vec3 sumM = vec3(0.0);
  float odR = 0.0;
  float odM = 0.0;
  vec2 hit = sphereHit(o, d, outer);
  if (hit.y > 0.0 && hit.x < hit.y) {
    float start = max(hit.x, 0.0);
    float end = hit.y;
    vec2 ground = sphereHit(o, d, radius);
    if (ground.x > 0.0 && ground.x < end) end = ground.x;
    float ds = (end - start) / steps;
    for (int i = 0; i < ${MAX_STEPS}; i++) {
      if (float(i) >= steps) break;
      vec3 p = o + d * (start + (float(i) + 0.5) * ds);
      float h = length(p) - radius;
      float dR = exp(-h / rayleighHeight) * ds;
      float dM = exp(-h / mieHeight) * ds;
      odR += dR;
      odM += dM;
      vec2 shadow = sphereHit(p, sun, radius);
      if (shadow.x > 0.0 && shadow.x < shadow.y) continue;
      float dl = sphereHit(p, sun, outer).y / lightSteps;
      float lR = 0.0;
      float lM = 0.0;
      for (int j = 0; j < ${MAX_LIGHT_STEPS}; j++) {
        if (float(j) >= lightSteps) break;
        float hq = length(p + sun * (float(j) + 0.5) * dl) - radius;
        lR += exp(-hq / rayleighHeight) * dl;
        lM += exp(-hq / mieHeight) * dl;
      }
      vec3 att = exp(-(rayleigh * (odR + lR) + mie * 1.1 * (odM + lM)));
      sumR += att * dR;
      sumM += att * dM;
    }
  }
  float mu = dot(d, sun);
  float phaseR = 3.0 / (16.0 * 3.14159265) * (1.0 + mu * mu);
  float g = 0.76;
  float phaseM = 3.0 / (8.0 * 3.14159265) * ((1.0 - g * g) * (1.0 + mu * mu)) / ((2.0 + g * g) * pow(1.0 + g * g - 2.0 * g * mu, 1.5));
  through = exp(-(rayleigh * odR + mie * 1.1 * odM));
  return 20.0 * (sumR * rayleigh * phaseR + sumM * mie * phaseM);
}
`;

// Where a direction lies in the sky's picture, and back (skyView.ts skyViewUnit, skyViewDirection).
const VIEW_GLSL = `
vec2 skyViewUnit(vec3 d) {
  float cz = clamp(dot(d, viewUp), -1.0, 1.0);
  float z = acos(cz);
  vec3 level = d - viewUp * cz;
  float fl = length(level);
  float ca = fl > 1e-6 ? clamp(dot(level, viewForward) / fl, -1.0, 1.0) : 1.0;
  float u = sqrt(max(0.0, 0.5 - 0.5 * ca));
  float v = z < viewHorizon ? 0.5 * (1.0 - sqrt(max(0.0, 1.0 - z / viewHorizon))) : 0.5 + 0.5 * sqrt(min(1.0, (z - viewHorizon) / viewBelow));
  return vec2(u, v);
}
vec3 skyViewDirection(float u, float v) {
  float ca = 1.0 - 2.0 * u * u;
  float sa = sqrt(max(0.0, 1.0 - ca * ca));
  float w = v < 0.5 ? 1.0 - 2.0 * v : 2.0 * v - 1.0;
  float z = v < 0.5 ? viewHorizon * (1.0 - w * w) : viewHorizon + viewBelow * w * w;
  return viewUp * cos(z) + sin(z) * (viewForward * ca + viewSide * sa);
}
`;

const SKY_GLSL = `
uniform mat4 toStars;
uniform float starDensity;
uniform float starSeed;
uniform float time;
// How many of the stars are drawn, 0 to 1: they fade in as the eye comes into the planet's hold, where the air seen from outside drew none.
uniform float airStrength;

vec3 starHash(vec3 p) {
  vec3 q = fract(p * vec3(0.1031, 0.103, 0.0973));
  q += dot(q, q.yxz + 33.33);
  return fract((q.xxy + q.yxx) * q.zyx);
}
// The stars toward d (in the stars' own sky), as the reference makes them (stars.ts).
vec3 starLight(vec3 d) {
  vec3 col = vec3(0.0);
  for (int l = 0; l < 2; l++) {
    float scale = l == 0 ? 220.0 : 700.0;
    float share = l == 0 ? 0.35 : 0.5;
    float bright = l == 0 ? 1.0 : 0.35;
    vec3 p = d * scale;
    vec3 c = floor(p);
    vec3 h = starHash(c + vec3(starSeed * 17.0, -starSeed * 31.0, starSeed * 7.0));
    if (h.x >= share * starDensity) continue;
    vec3 at = starHash(c + vec3(-5.0, 11.0 + starSeed, 3.0));
    vec3 s = c + 0.3 + 0.4 * at;
    vec3 off = (p - s) / 0.22;
    float fall = exp(-dot(off, off));
    // A slow twinkle, star by star.
    float glow = bright * (0.15 + 3.0 * pow(h.y, 8.0)) * fall * (0.85 + 0.15 * sin(time * 2.7 + h.z * 40.0));
    float t = h.z;
    vec3 tint = t < 0.5 ? vec3(0.8 + 0.4 * t, 0.88 + 0.24 * t, 1.12 - 0.12 * t) : vec3(1.0 + 0.25 * (t - 0.5), 1.0 - 0.2 * (t - 0.5), 1.0 - 0.5 * (t - 0.5));
    col += glow * tint;
  }
  return col;
}
// The sun toward cosine mu from it: a soft disc darker at its rim, in the glow the air scatters about it (atmosphere.ts sunGlow).
float sunGlow(float mu) {
  float angle = acos(clamp(mu, -1.0, 1.0));
  float r = angle / 0.008;
  float rim = 1.0 - 0.6 * (1.0 - sqrt(max(0.0, 1.0 - min(r, 1.0) * min(r, 1.0))));
  float disc = 40.0 * rim * (1.0 - smoothstep(0.85, 1.15, r));
  return disc + 0.6 * exp(-angle / 0.035) + 0.08 * exp(-angle / 0.15);
}
// The sky toward d: the air's light c, the sun in its glow through the air, tone-mapped, and the stars where it is dark.
vec3 skyFrom(vec3 c, vec3 through, vec3 d, vec3 sun) {
  c += sunGlow(dot(d, sun)) * through;
  vec3 sky = vec3(1.0) - exp(-c);
  float dark = clamp(1.0 - 8.0 * dot(sky, vec3(0.3, 0.59, 0.11)), 0.0, 1.0);
  // Where the sky is too bright for any star the stars are not looked for: in daylight, everywhere.
  if (dark > 0.0 && starDensity > 0.0) sky += starLight(normalize((toStars * vec4(d, 0.0)).xyz)) * dark * through * airStrength;
  return sky;
}
`;

const VERTEX_GLSL = `
precision highp float;
attribute vec3 position;
uniform mat4 world;
uniform mat4 worldViewProjection;
varying vec3 vWorld;
void main(void) {
  vWorld = (world * vec4(position, 1.0)).xyz;
  gl_Position = worldViewProjection * vec4(position, 1.0);
}`;

/** The sphere's shader that sums the air's light for each pixel. */
const FRAGMENT_GLSL = `
precision highp float;
varying vec3 vWorld;
${AIR_DECLARATIONS_GLSL}${AIR_GLSL}${SKY_GLSL}
void main(void) {
  vec3 d = normalize(vWorld - eye);
  vec3 sun = normalize(sunDirection);
  vec3 through;
  vec3 c = airLight(eye - centre, d, sun, through);
  gl_FragColor = vec4(skyFrom(c, through, d, sun), 1.0);
}`;

/** The sphere's shader that looks the air's light up in the sky's picture. */
const LOOKUP_FRAGMENT_GLSL = `
precision highp float;
varying vec3 vWorld;
uniform sampler2D skyView;
${AIR_DECLARATIONS_GLSL}${VIEW_GLSL}${SKY_GLSL}
void main(void) {
  vec3 d = normalize(vWorld - eye);
  vec3 sun = normalize(sunDirection);
  vec2 at = skyViewUnit(d);
  float y = (0.5 + at.y * ${f(SKY_VIEW_HEIGHT - 1)}) / ${f(SKY_VIEW_HEIGHT)};
  vec3 c = texture2D(skyView, vec2((0.5 + at.x * ${f(SKY_VIEW_BEARINGS - 1)}) / ${f(SKY_VIEW_WIDTH)}, y)).rgb;
  vec3 through = texture2D(skyView, vec2(${f(SKY_VIEW_BEARINGS + 1.5)} / ${f(SKY_VIEW_WIDTH)}, y)).rgb;
  gl_FragColor = vec4(skyFrom(c, through, d, sun), 1.0);
}`;

/** The sky's picture: each texel the air's light toward its direction, or in the last two columns the light let through. Its texel is found from the pixel drawn, which is the texel looked up in either engine. */
const PICTURE_GLSL = `
precision highp float;
${AIR_DECLARATIONS_GLSL}${AIR_GLSL}${VIEW_GLSL}
void main(void) {
  vec2 px = floor(gl_FragCoord.xy);
  bool through = px.x >= ${f(SKY_VIEW_BEARINGS)};
  vec3 d = skyViewDirection(through ? 0.0 : px.x / ${f(SKY_VIEW_BEARINGS - 1)}, px.y / ${f(SKY_VIEW_HEIGHT - 1)});
  vec3 t;
  vec3 c = airLight(eye - centre, d, normalize(sunDirection), t);
  gl_FragColor = vec4(through ? t : c, 1.0);
}`;

// ---- WGSL (WebGPU): the same sums, in Babylon's WGSL dialect. ----
const AIR_DECLARATIONS_WGSL = `
uniform eye: vec3f;
uniform centre: vec3f;
uniform sunDirection: vec3f;
uniform radius: f32;
uniform top: f32;
uniform rayleighHeight: f32;
uniform mieHeight: f32;
uniform rayleigh: vec3f;
uniform mie: f32;
uniform steps: f32;
uniform lightSteps: f32;
uniform viewUp: vec3f;
uniform viewForward: vec3f;
uniform viewSide: vec3f;
uniform viewHorizon: f32;
uniform viewBelow: f32;
`;

const AIR_WGSL = `
fn sphereHit(o: vec3f, d: vec3f, r: f32) -> vec2f {
  let b = dot(o, d);
  let c = dot(o, o) - r * r;
  let disc = b * b - c;
  if (disc < 0.0) { return vec2f(1e20, -1e20); }
  let s = sqrt(disc);
  return vec2f(-b - s, -b + s);
}
struct AirLight {
  scatter: vec3f,
  through: vec3f,
}
fn airLight(o: vec3f, d: vec3f, sun: vec3f) -> AirLight {
  let radius = uniforms.radius;
  let outer = radius + uniforms.top;
  var sumR = vec3f(0.0);
  var sumM = vec3f(0.0);
  var odR: f32 = 0.0;
  var odM: f32 = 0.0;
  let hit = sphereHit(o, d, outer);
  if (hit.y > 0.0 && hit.x < hit.y) {
    let start = max(hit.x, 0.0);
    var end = hit.y;
    let ground = sphereHit(o, d, radius);
    if (ground.x > 0.0 && ground.x < end) { end = ground.x; }
    let ds = (end - start) / uniforms.steps;
    for (var i: i32 = 0; i < ${MAX_STEPS}; i++) {
      if (f32(i) >= uniforms.steps) { break; }
      let p = o + d * (start + (f32(i) + 0.5) * ds);
      let h = length(p) - radius;
      let dR = exp(-h / uniforms.rayleighHeight) * ds;
      let dM = exp(-h / uniforms.mieHeight) * ds;
      odR += dR;
      odM += dM;
      let shadow = sphereHit(p, sun, radius);
      if (shadow.x > 0.0 && shadow.x < shadow.y) { continue; }
      let dl = sphereHit(p, sun, outer).y / uniforms.lightSteps;
      var lR: f32 = 0.0;
      var lM: f32 = 0.0;
      for (var j: i32 = 0; j < ${MAX_LIGHT_STEPS}; j++) {
        if (f32(j) >= uniforms.lightSteps) { break; }
        let hq = length(p + sun * (f32(j) + 0.5) * dl) - radius;
        lR += exp(-hq / uniforms.rayleighHeight) * dl;
        lM += exp(-hq / uniforms.mieHeight) * dl;
      }
      let att = exp(-(uniforms.rayleigh * (odR + lR) + vec3f(uniforms.mie * 1.1 * (odM + lM))));
      sumR += att * dR;
      sumM += att * dM;
    }
  }
  let mu = dot(d, sun);
  let phaseR = 3.0 / (16.0 * 3.14159265) * (1.0 + mu * mu);
  let g: f32 = 0.76;
  let phaseM = 3.0 / (8.0 * 3.14159265) * ((1.0 - g * g) * (1.0 + mu * mu)) / ((2.0 + g * g) * pow(1.0 + g * g - 2.0 * g * mu, 1.5));
  let through = exp(-(uniforms.rayleigh * odR + vec3f(uniforms.mie * 1.1 * odM)));
  return AirLight(20.0 * (sumR * uniforms.rayleigh * phaseR + sumM * uniforms.mie * phaseM), through);
}
`;

const VIEW_WGSL = `
fn skyViewUnit(d: vec3f) -> vec2f {
  let cz = clamp(dot(d, uniforms.viewUp), -1.0, 1.0);
  let z = acos(cz);
  let level = d - uniforms.viewUp * cz;
  let fl = length(level);
  var ca: f32 = 1.0;
  if (fl > 1e-6) { ca = clamp(dot(level, uniforms.viewForward) / fl, -1.0, 1.0); }
  let u = sqrt(max(0.0, 0.5 - 0.5 * ca));
  var v = 0.5 + 0.5 * sqrt(min(1.0, (z - uniforms.viewHorizon) / uniforms.viewBelow));
  if (z < uniforms.viewHorizon) { v = 0.5 * (1.0 - sqrt(max(0.0, 1.0 - z / uniforms.viewHorizon))); }
  return vec2f(u, v);
}
fn skyViewDirection(u: f32, v: f32) -> vec3f {
  let ca = 1.0 - 2.0 * u * u;
  let sa = sqrt(max(0.0, 1.0 - ca * ca));
  var z: f32;
  if (v < 0.5) { let w = 1.0 - 2.0 * v; z = uniforms.viewHorizon * (1.0 - w * w); } else { let w = 2.0 * v - 1.0; z = uniforms.viewHorizon + uniforms.viewBelow * w * w; }
  return uniforms.viewUp * cos(z) + sin(z) * (uniforms.viewForward * ca + uniforms.viewSide * sa);
}
`;

const SKY_WGSL = `
uniform toStars: mat4x4f;
uniform starDensity: f32;
uniform starSeed: f32;
uniform time: f32;
uniform airStrength: f32;

fn starHash(p: vec3f) -> vec3f {
  var q = fract(p * vec3f(0.1031, 0.103, 0.0973));
  q += dot(q, q.yxz + 33.33);
  return fract((q.xxy + q.yxx) * q.zyx);
}
fn starLight(d: vec3f) -> vec3f {
  var col = vec3f(0.0);
  for (var l: i32 = 0; l < 2; l++) {
    var scale: f32 = 220.0;
    var share: f32 = 0.35;
    var bright: f32 = 1.0;
    if (l == 1) { scale = 700.0; share = 0.5; bright = 0.35; }
    let p = d * scale;
    let c = floor(p);
    let seed = uniforms.starSeed;
    let h = starHash(c + vec3f(seed * 17.0, -seed * 31.0, seed * 7.0));
    if (h.x >= share * uniforms.starDensity) { continue; }
    let at = starHash(c + vec3f(-5.0, 11.0 + seed, 3.0));
    let s = c + 0.3 + 0.4 * at;
    let off = (p - s) / 0.22;
    let fall = exp(-dot(off, off));
    let glow = bright * (0.15 + 3.0 * pow(h.y, 8.0)) * fall * (0.85 + 0.15 * sin(uniforms.time * 2.7 + h.z * 40.0));
    let t = h.z;
    var tint = vec3f(1.0 + 0.25 * (t - 0.5), 1.0 - 0.2 * (t - 0.5), 1.0 - 0.5 * (t - 0.5));
    if (t < 0.5) { tint = vec3f(0.8 + 0.4 * t, 0.88 + 0.24 * t, 1.12 - 0.12 * t); }
    col += glow * tint;
  }
  return col;
}
fn sunGlow(mu: f32) -> f32 {
  let angle = acos(clamp(mu, -1.0, 1.0));
  let r = angle / 0.008;
  let rr = min(r, 1.0);
  let rim = 1.0 - 0.6 * (1.0 - sqrt(max(0.0, 1.0 - rr * rr)));
  let disc = 40.0 * rim * (1.0 - smoothstep(0.85, 1.15, r));
  return disc + 0.6 * exp(-angle / 0.035) + 0.08 * exp(-angle / 0.15);
}
fn skyFrom(light: vec3f, through: vec3f, d: vec3f, sun: vec3f) -> vec3f {
  let c = light + sunGlow(dot(d, sun)) * through;
  var sky = vec3f(1.0) - exp(-c);
  let dark = clamp(1.0 - 8.0 * dot(sky, vec3f(0.3, 0.59, 0.11)), 0.0, 1.0);
  // Where the sky is too bright for any star the stars are not looked for: in daylight, everywhere.
  if (dark > 0.0 && uniforms.starDensity > 0.0) { sky += starLight(normalize((uniforms.toStars * vec4f(d, 0.0)).xyz)) * dark * through * uniforms.airStrength; }
  return sky;
}
`;

const VERTEX_WGSL = `
attribute position: vec3f;
uniform world: mat4x4f;
uniform worldViewProjection: mat4x4f;
varying vWorld: vec3f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  vertexOutputs.vWorld = (uniforms.world * vec4f(vertexInputs.position, 1.0)).xyz;
  vertexOutputs.position = uniforms.worldViewProjection * vec4f(vertexInputs.position, 1.0);
}`;

const FRAGMENT_WGSL = `
varying vWorld: vec3f;
${AIR_DECLARATIONS_WGSL}${AIR_WGSL}${SKY_WGSL}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let d = normalize(input.vWorld - uniforms.eye);
  let sun = normalize(uniforms.sunDirection);
  let l = airLight(uniforms.eye - uniforms.centre, d, sun);
  fragmentOutputs.color = vec4f(skyFrom(l.scatter, l.through, d, sun), 1.0);
}`;

const LOOKUP_FRAGMENT_WGSL = `
varying vWorld: vec3f;
var skyViewSampler: sampler;
var skyView: texture_2d<f32>;
${AIR_DECLARATIONS_WGSL}${VIEW_WGSL}${SKY_WGSL}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let d = normalize(input.vWorld - uniforms.eye);
  let sun = normalize(uniforms.sunDirection);
  let at = skyViewUnit(d);
  let y = (0.5 + at.y * ${f(SKY_VIEW_HEIGHT - 1)}) / ${f(SKY_VIEW_HEIGHT)};
  let c = textureSample(skyView, skyViewSampler, vec2f((0.5 + at.x * ${f(SKY_VIEW_BEARINGS - 1)}) / ${f(SKY_VIEW_WIDTH)}, y)).rgb;
  let through = textureSample(skyView, skyViewSampler, vec2f(${f(SKY_VIEW_BEARINGS + 1.5)} / ${f(SKY_VIEW_WIDTH)}, y)).rgb;
  fragmentOutputs.color = vec4f(skyFrom(c, through, d, sun), 1.0);
}`;

const PICTURE_WGSL = `
varying vUV: vec2f;
${AIR_DECLARATIONS_WGSL}${AIR_WGSL}${VIEW_WGSL}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let px = floor(fragmentInputs.position.xy);
  let through = px.x >= ${f(SKY_VIEW_BEARINGS)};
  var u: f32 = 0.0;
  if (!through) { u = px.x / ${f(SKY_VIEW_BEARINGS - 1)}; }
  let d = skyViewDirection(u, px.y / ${f(SKY_VIEW_HEIGHT - 1)});
  let l = airLight(uniforms.eye - uniforms.centre, d, normalize(uniforms.sunDirection));
  var c = l.scatter;
  if (through) { c = l.through; }
  fragmentOutputs.color = vec4f(c, 1.0);
}`;

// ---- The air seen from outside: a shell over a planet that does not hold the visitor ----

/**
 * How much of the air's summed light and dimming the shell lays over the
 * ground. The sky's air is tuned for the sky seen from inside; over the ground
 * the planet that holds the visitor lays a lighter haze of its own (the air's
 * veil), and the shell matches that, by eye, so the planet looks the same either
 * side of its hold's edge. Its rim, where the line meets no ground, is the sky's.
 * This is the shell's own, at `planet.haze` 1: the planet's haze scales it
 * (`groundHaze`), as it scales the haze seen from inside.
 */
const SHELL_GROUND_HAZE = 0.35;

/**
 * The shell's shader: the light the air scatters toward the eye along each
 * line through it, and as its alpha what of the light behind the air does not
 * come through (the ground's, or space's). Premultiplied, so the ground or the
 * stars behind dim by the air in front and the air's own light adds to them.
 */
export const SHELL_FRAGMENT_GLSL = `
precision highp float;
varying vec3 vWorld;
uniform float airStrength;
uniform float groundHaze;
${AIR_DECLARATIONS_GLSL}${AIR_GLSL}
void main(void) {
  vec3 d = normalize(vWorld - eye);
  vec3 sun = normalize(sunDirection);
  vec3 through;
  vec3 c = airLight(eye - centre, d, sun, through);
  vec3 light = vec3(1.0) - exp(-c);
  float alpha = clamp(1.0 - dot(through, vec3(1.0 / 3.0)), 0.0, 1.0);
  vec2 ground = sphereHit(eye - centre, d, radius);
  if (ground.x > 0.0 && ground.x < ground.y) {
    light *= ${f(SHELL_GROUND_HAZE)} * groundHaze;
    alpha *= ${f(SHELL_GROUND_HAZE)} * groundHaze;
  }
  gl_FragColor = vec4(light, alpha) * airStrength;
}`;

export const SHELL_FRAGMENT_WGSL = `
varying vWorld: vec3f;
uniform airStrength: f32;
uniform groundHaze: f32;
${AIR_DECLARATIONS_WGSL}${AIR_WGSL}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let d = normalize(input.vWorld - uniforms.eye);
  let sun = normalize(uniforms.sunDirection);
  let l = airLight(uniforms.eye - uniforms.centre, d, sun);
  var light = vec3f(1.0) - exp(-l.scatter);
  var alpha = clamp(1.0 - dot(l.through, vec3f(1.0 / 3.0)), 0.0, 1.0);
  let ground = sphereHit(uniforms.eye - uniforms.centre, d, uniforms.radius);
  if (ground.x > 0.0 && ground.x < ground.y) {
    light = light * ${f(SHELL_GROUND_HAZE)} * uniforms.groundHaze;
    alpha = alpha * ${f(SHELL_GROUND_HAZE)} * uniforms.groundHaze;
  }
  fragmentOutputs.color = vec4f(light, alpha) * uniforms.airStrength;
}`;

/** Every input the shell's shader takes, in both languages. */
export const AIR_SHELL_UNIFORMS = ['world', 'worldViewProjection', 'eye', 'centre', 'sunDirection', ...AIR_UNIFORMS, ...VIEW_FRAME_UNIFORMS, 'airStrength', 'groundHaze'] as const;

export interface AtmosphereShaderSources {
  shaderLanguage: ShaderLanguage;
  vertexSource: string;
  /** The sphere's shader, summing the air's light for each pixel. */
  fragmentSource: string;
  /** The sphere's shader, looking it up in the sky's picture. */
  lookupFragmentSource: string;
  /** The sky's picture's shader. */
  pictureSource: string;
}

/** WGSL on WebGPU, natively; GLSL on every other engine. */
// ---- The stars and the sun with no air before them: in space, and in the sky of a planet with no air ----

/**
 * A sphere about the eye, drawn at the far plane (its depth is the farthest
 * there is, so whatever stands anywhere in front of it hides it, drawn before
 * or after), with the sun's disc and the stars the planet's own sky shows, in
 * the same place: so they do not move as the eye comes into the planet's air.
 */
const STARS_VERTEX_GLSL = `
precision highp float;
attribute vec3 position;
uniform mat4 view;
uniform mat4 projection;
varying vec3 vDir;
void main(void) {
  vDir = position;
  vec4 p = projection * vec4((view * vec4(position, 0.0)).xyz, 1.0);
  gl_Position = p.xyww;
}`;

const STARS_FRAGMENT_GLSL = `
precision highp float;
varying vec3 vDir;
uniform vec3 sunDirection;
${SKY_GLSL}
void main(void) {
  vec3 d = normalize(vDir);
  vec3 sky = vec3(1.0) - exp(-sunGlow(dot(d, normalize(sunDirection))) * vec3(1.0, 0.98, 0.94));
  if (starDensity > 0.0) sky += starLight(normalize((toStars * vec4(d, 0.0)).xyz)) * airStrength;
  gl_FragColor = vec4(sky, 1.0);
}`;

const STARS_VERTEX_WGSL = `
attribute position: vec3f;
uniform view: mat4x4f;
uniform projection: mat4x4f;
varying vDir: vec3f;
@vertex
fn main(input: VertexInputs) -> FragmentInputs {
  vertexOutputs.vDir = vertexInputs.position;
  let p = uniforms.projection * vec4f((uniforms.view * vec4f(vertexInputs.position, 0.0)).xyz, 1.0);
  vertexOutputs.position = vec4f(p.x, p.y, p.w, p.w);
}`;

const STARS_FRAGMENT_WGSL = `
varying vDir: vec3f;
uniform sunDirection: vec3f;
${SKY_WGSL}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let d = normalize(fragmentInputs.vDir);
  var sky = vec3f(1.0) - exp(-sunGlow(dot(d, normalize(uniforms.sunDirection))) * vec3f(1.0, 0.98, 0.94));
  if (uniforms.starDensity > 0.0) { sky += starLight(normalize((uniforms.toStars * vec4f(d, 0.0)).xyz)) * uniforms.airStrength; }
  fragmentOutputs.color = vec4f(sky, 1.0);
}`;

/** The star field's shaders: WGSL on WebGPU, GLSL elsewhere. */
export function selectStarFieldSources(engineKind?: string): { vertexSource: string; fragmentSource: string; shaderLanguage: ShaderLanguage } {
  return engineKind === 'webgpu'
    ? { vertexSource: STARS_VERTEX_WGSL, fragmentSource: STARS_FRAGMENT_WGSL, shaderLanguage: ShaderLanguage.WGSL }
    : { vertexSource: STARS_VERTEX_GLSL, fragmentSource: STARS_FRAGMENT_GLSL, shaderLanguage: ShaderLanguage.GLSL };
}

export function createStarField(scene: Scene, opts: { engineKind?: string }): StarFieldHandle {
  const sources = selectStarFieldSources(opts.engineKind);
  const mesh = CreateSphere('starField', { diameter: 2, segments: 32, sideOrientation: Mesh.BACKSIDE }, scene);
  mesh.isPickable = false;
  mesh.applyFog = false;
  // About the eye wherever it goes: drawn by direction alone (the view's turn, not its place), and in every frame. Its
  // place, worked out a frame behind a fast eye, lay kilometres off and out of view, and the stars went.
  mesh.infiniteDistance = true;
  mesh.alwaysSelectAsActiveMesh = true;
  const material = new ShaderMaterial(
    'starField',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: sources.fragmentSource },
    { attributes: ['position'], uniforms: ['view', 'projection', 'sunDirection', 'toStars', 'starDensity', 'starSeed', 'time', 'airStrength'], shaderLanguage: sources.shaderLanguage },
  );
  material.disableDepthWrite = true;
  material.setVector3('sunDirection', new Vector3(0, 1, 0));
  material.setMatrix('toStars', Matrix.Identity());
  material.setFloat('starDensity', 0);
  material.setFloat('starSeed', 1);
  material.setFloat('time', 0);
  material.setFloat('airStrength', 1);
  mesh.material = material;
  return {
    update(_eye, sun, sky) {
      material.setVector3('sunDirection', sun);
      material.setMatrix('toStars', sky.toStars);
      material.setFloat('starDensity', sky.starDensity);
      material.setFloat('starSeed', sky.starSeed);
      material.setFloat('time', sky.timeS);
    },
    setEnabled(on) {
      mesh.setEnabled(on);
    },
    isReady: () => material.isReady(mesh),
    dispose() {
      mesh.dispose(false, false);
      material.dispose();
    },
  };
}

export function selectAtmosphereShaderSources(engineKind?: string): AtmosphereShaderSources {
  return engineKind === 'webgpu'
    ? { shaderLanguage: ShaderLanguage.WGSL, vertexSource: VERTEX_WGSL, fragmentSource: FRAGMENT_WGSL, lookupFragmentSource: LOOKUP_FRAGMENT_WGSL, pictureSource: PICTURE_WGSL }
    : { shaderLanguage: ShaderLanguage.GLSL, vertexSource: VERTEX_GLSL, fragmentSource: FRAGMENT_GLSL, lookupFragmentSource: LOOKUP_FRAGMENT_GLSL, pictureSource: PICTURE_GLSL };
}

/** How far past the eye the sky reaches once the eye is above the air, as a share of its distance from the planet's centre. */
export const SKY_ENCLOSES = 1.05;

/** A shader's inputs that both the sphere and the sky's picture set. */
interface AirInputs {
  setFloat(name: string, v: number): unknown;
  setVector3(name: string, v: Vector3): unknown;
  setColor3(name: string, v: Color3): unknown;
}

function setAir(m: AirInputs, a: Atmosphere, opts: { steps: number; lightSteps: number }): void {
  m.setFloat('radius', a.radius);
  m.setFloat('top', a.top);
  m.setFloat('rayleighHeight', a.rayleighHeight);
  m.setFloat('mieHeight', a.mieHeight);
  m.setColor3('rayleigh', new Color3(...a.rayleigh));
  m.setFloat('mie', a.mie);
  m.setFloat('steps', Math.min(opts.steps, MAX_STEPS));
  m.setFloat('lightSteps', Math.min(opts.lightSteps, MAX_LIGHT_STEPS));
}

function setFrame(m: AirInputs, eye: Vector3, centre: Vector3, sun: Vector3, a: Atmosphere): void {
  m.setVector3('eye', eye);
  m.setVector3('centre', centre);
  m.setVector3('sunDirection', sun);
  const o = eye.subtract(centre);
  const v = skyViewFrame(a, [o.x, o.y, o.z], [sun.x, sun.y, sun.z]);
  m.setVector3('viewUp', new Vector3(...v.up));
  m.setVector3('viewForward', new Vector3(...v.forward));
  m.setVector3('viewSide', new Vector3(...v.side));
  m.setFloat('viewHorizon', v.horizon);
  m.setFloat('viewBelow', v.below);
}

/**
 * The sky. `lookup` false sums the air's light for every pixel; by default
 * the sky's picture is drawn and looked up wherever the engine can draw it in
 * floating point.
 */
export function createAtmosphere(scene: Scene, a: Atmosphere, opts: { engineKind?: string; steps: number; lightSteps: number; lookup?: boolean }): AtmosphereHandle {
  const sources = selectAtmosphereShaderSources(opts.engineKind);
  const engine = scene.getEngine();
  const lookup = opts.lookup !== false && engine.getCaps().textureHalfFloatRender === true;
  const mesh = CreateSphere('atmosphere', { diameter: 2 * (a.radius + a.top), segments: 64, sideOrientation: Mesh.BACKSIDE }, scene);
  mesh.isPickable = false;
  mesh.applyFog = false;
  let picture: ProceduralTexture | undefined;
  if (lookup) {
    picture = new ProceduralTexture(
      'skyView',
      { width: SKY_VIEW_WIDTH, height: SKY_VIEW_HEIGHT },
      { fragmentSource: sources.pictureSource },
      scene,
      { shaderLanguage: sources.shaderLanguage },
      false,
      false,
      Constants.TEXTURETYPE_HALF_FLOAT,
    );
    picture.wrapU = Texture.CLAMP_ADDRESSMODE;
    picture.wrapV = Texture.CLAMP_ADDRESSMODE;
    picture.updateSamplingMode(Texture.BILINEAR_SAMPLINGMODE);
    setAir(picture, a, opts);
  }
  const material = new ShaderMaterial(
    'atmosphere',
    scene,
    { vertexSource: sources.vertexSource, fragmentSource: picture ? sources.lookupFragmentSource : sources.fragmentSource },
    // In the queue drawn after the opaque ground, so the ground it lies behind hides it before it is shaded; it tests nothing.
    { attributes: ['position'], uniforms: [...ATMOSPHERE_UNIFORMS], samplers: picture ? ['skyView'] : [], shaderLanguage: sources.shaderLanguage, needAlphaTesting: true },
  );
  // Behind everything it sits behind, and never hiding it.
  material.disableDepthWrite = true;
  setAir(material, a, opts);
  if (picture) material.setTexture('skyView', picture);
  // No stars until the view says which, and how they have turned.
  material.setMatrix('toStars', Matrix.Identity());
  material.setFloat('starDensity', 0);
  material.setFloat('starSeed', 1);
  material.setFloat('time', 0);
  material.setFloat('airStrength', 1);
  mesh.material = material;
  return {
    update(eye, centre, sun, sky) {
      if (sky) {
        material.setMatrix('toStars', sky.toStars);
        material.setFloat('starDensity', sky.starDensity);
        material.setFloat('starSeed', sky.starSeed);
        material.setFloat('time', sky.timeS);
        material.setFloat('airStrength', sky.strength ?? 1);
      }
      mesh.position.copyFrom(centre);
      // Above the air the shell no longer surrounds the eye, and space would be
      // drawn only where the air lies before it: the stars elsewhere would be
      // missing. Grown past the eye, the sky lies all round it; the scattering
      // still uses the air's own height, so what it draws is the same.
      mesh.scaling.setAll(Math.max(1, (Vector3.Distance(eye, centre) * SKY_ENCLOSES) / (a.radius + a.top)));
      const s = sun.normalizeToNew();
      setFrame(material, eye, centre, s, a);
      if (picture) setFrame(picture, eye, centre, s, a);
    },
    isReady: () => material.isReady(mesh) && (!picture || picture.isReady()),
    dispose() {
      mesh.dispose(false, false);
      material.dispose();
      picture?.dispose();
    },
  };
}

/**
 * A planet's air as seen from outside it, over a planet that does not hold
 * the visitor: a sphere at the top of its air, drawn in front of its ground
 * and the stars, its light added and what it lets through kept. The planet
 * may be drawn smaller about a point, so it looks the same from the eye
 * (planetView's `near`): `update` takes where it is drawn and how much
 * smaller, and sums the air at the planet's own size.
 */
export function createAirShell(scene: Scene, a: Atmosphere, opts: { engineKind?: string; steps: number; lightSteps: number; renderingGroupId?: number }): AirShellHandle {
  const webgpu = opts.engineKind === 'webgpu';
  const mesh = CreateSphere('airShell', { diameter: 2 * (a.radius + a.top), segments: 64 }, scene);
  mesh.isPickable = false;
  mesh.applyFog = false;
  if (opts.renderingGroupId !== undefined) mesh.renderingGroupId = opts.renderingGroupId;
  const material = new ShaderMaterial(
    'airShell',
    scene,
    { vertexSource: webgpu ? VERTEX_WGSL : VERTEX_GLSL, fragmentSource: webgpu ? SHELL_FRAGMENT_WGSL : SHELL_FRAGMENT_GLSL },
    { attributes: ['position'], uniforms: [...AIR_SHELL_UNIFORMS], shaderLanguage: webgpu ? ShaderLanguage.WGSL : ShaderLanguage.GLSL, needAlphaBlending: true },
  );
  material.alphaMode = Constants.ALPHA_PREMULTIPLIED;
  material.disableDepthWrite = true;
  setAir(material, a, opts);
  material.setFloat('airStrength', 1);
  material.setFloat('groundHaze', 1);
  mesh.material = material;
  return {
    update(eye, drawnCentre, scale, sun, strength = 1, haze = 1) {
      mesh.position.copyFrom(drawnCentre);
      mesh.scaling.setAll(scale);
      // The air summed at the planet's own size: the eye as far from its centre, at its own size, as it is from the
      // centre drawn smaller. Only the eye's offset from the centre matters to the sum, and the line's direction,
      // which drawing smaller about a point does not turn.
      const k = scale > 0 ? scale : 1;
      const centre = eye.subtract(eye.subtract(drawnCentre).scale(1 / k));
      setFrame(material, eye, centre, sun.normalizeToNew(), a);
      material.setFloat('airStrength', strength);
      material.setFloat('groundHaze', haze);
    },
    setEnabled(on) {
      mesh.setEnabled(on);
    },
    isReady: () => material.isReady(mesh),
    dispose() {
      mesh.dispose(false, false);
      material.dispose();
    },
  };
}

// ---- The air's veil: haze and fog summed along the eye's line, on every lit material ----

/** Every input the veil takes, in both languages. */
export const AIR_VEIL_UNIFORMS = [
  'airVeilEye',
  'airVeilCentre',
  'airVeilToPlanet',
  'airVeilSun',
  'airVeilRadius',
  'airVeilFogDensity',
  'airVeilFogHeight',
  'airVeilFogColor',
  'airVeilPatchiness',
  'airVeilPatchSize',
  'airVeilHazeBeta',
  'airVeilHazeHeight',
  'airVeilHazeToward',
  'airVeilHazeAway',
  'airVeilHazeZenith',
  'airVeilFogFloor',
  'airVeilEyeAltitude',
  'airVeilEyeUp',
  'airVeilSunLevel',
] as const;

/** The cloud noise, renamed for the veil: a material may carry the clouds' shadows too, and a name is declared once. */
const VEIL_NOISE_GLSL = NOISE_GLSL.replace(/cloud(Hash|ValueNoise|DensityOf)/g, 'veil$1');
const VEIL_NOISE_WGSL = NOISE_WGSL.replace(/cloud(Hash|ValueNoise|DensityOf)/g, 'veil$1');

const VEIL_UNIFORMS_GLSL = `#ifdef AIRVEIL
uniform vec3 airVeilEye;
uniform vec3 airVeilCentre;
uniform mat4 airVeilToPlanet;
uniform vec3 airVeilSun;
uniform float airVeilRadius;
uniform float airVeilFogDensity;
uniform float airVeilFogHeight;
uniform vec3 airVeilFogColor;
uniform float airVeilPatchiness;
uniform float airVeilPatchSize;
uniform float airVeilHazeBeta;
uniform float airVeilHazeHeight;
uniform vec3 airVeilHazeToward;
uniform vec3 airVeilHazeAway;
uniform vec3 airVeilHazeZenith;
uniform float airVeilFogFloor;
uniform float airVeilEyeAltitude;
uniform vec3 airVeilEyeUp;
uniform vec3 airVeilSunLevel;
#endif
`;

const VEIL_UNIFORMS_WGSL = `#ifdef AIRVEIL
uniform airVeilEye: vec3f;
uniform airVeilCentre: vec3f;
uniform airVeilToPlanet: mat4x4f;
uniform airVeilSun: vec3f;
uniform airVeilRadius: f32;
uniform airVeilFogDensity: f32;
uniform airVeilFogHeight: f32;
uniform airVeilFogColor: vec3f;
uniform airVeilPatchiness: f32;
uniform airVeilPatchSize: f32;
uniform airVeilHazeBeta: f32;
uniform airVeilHazeHeight: f32;
uniform airVeilHazeToward: vec3f;
uniform airVeilHazeAway: vec3f;
uniform airVeilHazeZenith: vec3f;
uniform airVeilFogFloor: f32;
uniform airVeilEyeAltitude: f32;
uniform airVeilEyeUp: vec3f;
uniform airVeilSunLevel: vec3f;
#endif
`;

// The fog's patches, for each vertex: they change over kilometres, far more slowly than from one vertex of the ground to the next,
// so they are worked out where the ground's corners are and spread across it, not again for every pixel.
const VEIL_VERTEX_GLSL = `#ifdef AIRVEIL
${VEIL_NOISE_GLSL}
varying float vAirVeilWet;
// How damp the place under the world point posW is, 0 to 1 (fog.ts humidity): 1 without fog or patches.
float airVeilWet(vec3 posW) {
  if (airVeilFogDensity <= 0.0 || airVeilPatchiness <= 0.0) return 1.0;
  vec3 d = (airVeilToPlanet * vec4(normalize(posW - airVeilCentre), 0.0)).xyz;
  float k = airVeilRadius / airVeilPatchSize;
  vec3 q = vec3(d.x * k + 17.3, d.y * k, d.z * k - 5.1);
  float n = (veilValueNoise(q) + 0.5 * veilValueNoise(q * 2.0) + 0.25 * veilValueNoise(q * 4.0)) / 1.75;
  return 1.0 - airVeilPatchiness * (1.0 - smoothstep(0.35, 0.65, n));
}
#endif
`;

const VEIL_DEFINITIONS_GLSL = `#ifdef AIRVEIL
varying float vAirVeilWet;
// The thickness along a line, the altitude changing evenly from a0 to a1, of a medium falling by e every height metres.
float airVeilDepth(float density, float height, float a0, float a1, float len) {
  if (density <= 0.0 || len <= 0.0) return 0.0;
  float u0 = max(a0, 0.0) / height;
  float u1 = max(a1, 0.0) / height;
  float du = u1 - u0;
  if (abs(du) < 1e-4) return density * len * exp(-u0);
  return density * len * (exp(-u0) - exp(-u1)) / du;
}
// What the eye sees of colour c at the world point posW, as damp as wet, through the haze and fog between; linearSpace > 0.5 where c is linear light.
// What is the same for every point (the eye's altitude and up, the sun's bearing level with the eye's ground) comes made, once a frame.
vec3 airVeil(vec3 c, vec3 posW, float wet, float linearSpace) {
  vec3 fromCentre = posW - airVeilCentre;
  float rp = length(fromCentre);
  float ap = rp - airVeilRadius;
  vec3 toPoint = posW - airVeilEye;
  float len = length(toPoint);
  float tf = 0.0;
  // No fog, nothing of it to work out.
  if (airVeilFogDensity > 0.0) {
    float sunUp = dot(fromCentre / rp, airVeilSun);
    float dawn = sunUp < 0.1 ? 0.6 + 0.4 * smoothstep(-0.3, 0.0, sunUp) : 1.0 - 0.85 * smoothstep(0.1, 0.55, sunUp);
    tf = airVeilDepth(airVeilFogDensity, airVeilFogHeight, airVeilEyeAltitude - airVeilFogFloor, ap - airVeilFogFloor, len) * dawn * wet;
  }
  float th = airVeilDepth(airVeilHazeBeta, airVeilHazeHeight, airVeilEyeAltitude, ap, len);
  if (tf + th <= 0.0) return c;
  // Fog hides as thickness does; haze as aerial haze is seen, little near and most far off.
  float seenFog = exp(-tf);
  float seenHaze = exp(-th * th * 1.4427);
  float wf = 1.0 - seenFog;
  float wh = 1.0 - seenHaze;
  // The haze is the sky's colour the way the eye looks: level toward the sun or away from it, or overhead.
  vec3 look = toPoint / len;
  float rise = dot(look, airVeilEyeUp);
  vec3 lookLevel = look - airVeilEyeUp * rise;
  float ll = dot(lookLevel, lookLevel);
  float facing = ll > 1e-8 ? dot(lookLevel, airVeilSunLevel) * inversesqrt(ll) : 0.0;
  vec3 hazeColor = mix(mix(airVeilHazeAway, airVeilHazeToward, 0.5 + 0.5 * facing), airVeilHazeZenith, clamp(rise, 0.0, 1.0));
  vec3 veil = (wf * airVeilFogColor + wh * hazeColor) / max(wf + wh, 1e-6);
  // The veil's colours are given as shown; a linear colour takes them in linear light.
  if (linearSpace > 0.5) veil = pow(veil, vec3(2.2));
  return mix(veil, c, seenFog * seenHaze);
}
#endif
`;

const VEIL_VERTEX_WGSL = `#ifdef AIRVEIL
${VEIL_NOISE_WGSL}
varying vAirVeilWet: f32;
fn airVeilWet(posW: vec3f) -> f32 {
  if (uniforms.airVeilFogDensity <= 0.0 || uniforms.airVeilPatchiness <= 0.0) { return 1.0; }
  let d = (uniforms.airVeilToPlanet * vec4f(normalize(posW - uniforms.airVeilCentre), 0.0)).xyz;
  let k = uniforms.airVeilRadius / uniforms.airVeilPatchSize;
  let q = vec3f(d.x * k + 17.3, d.y * k, d.z * k - 5.1);
  let n = (veilValueNoise(q) + 0.5 * veilValueNoise(q * 2.0) + 0.25 * veilValueNoise(q * 4.0)) / 1.75;
  return 1.0 - uniforms.airVeilPatchiness * (1.0 - smoothstep(0.35, 0.65, n));
}
#endif
`;

const VEIL_DEFINITIONS_WGSL = `#ifdef AIRVEIL
varying vAirVeilWet: f32;
fn airVeilDepth(density: f32, height: f32, a0: f32, a1: f32, len: f32) -> f32 {
  if (density <= 0.0 || len <= 0.0) { return 0.0; }
  let u0 = max(a0, 0.0) / height;
  let u1 = max(a1, 0.0) / height;
  let du = u1 - u0;
  if (abs(du) < 1e-4) { return density * len * exp(-u0); }
  return density * len * (exp(-u0) - exp(-u1)) / du;
}
fn airVeil(c: vec3f, posW: vec3f, wet: f32, linearSpace: f32) -> vec3f {
  let fromCentre = posW - uniforms.airVeilCentre;
  let rp = length(fromCentre);
  let ap = rp - uniforms.airVeilRadius;
  let toPoint = posW - uniforms.airVeilEye;
  let len = length(toPoint);
  var tf: f32 = 0.0;
  if (uniforms.airVeilFogDensity > 0.0) {
    let sunUp = dot(fromCentre / rp, uniforms.airVeilSun);
    var dawn: f32 = 1.0 - 0.85 * smoothstep(0.1, 0.55, sunUp);
    if (sunUp < 0.1) { dawn = 0.6 + 0.4 * smoothstep(-0.3, 0.0, sunUp); }
    tf = airVeilDepth(uniforms.airVeilFogDensity, uniforms.airVeilFogHeight, uniforms.airVeilEyeAltitude - uniforms.airVeilFogFloor, ap - uniforms.airVeilFogFloor, len) * dawn * wet;
  }
  let th = airVeilDepth(uniforms.airVeilHazeBeta, uniforms.airVeilHazeHeight, uniforms.airVeilEyeAltitude, ap, len);
  if (tf + th <= 0.0) { return c; }
  let seenFog = exp(-tf);
  let seenHaze = exp(-th * th * 1.4427);
  let wf = 1.0 - seenFog;
  let wh = 1.0 - seenHaze;
  let look = toPoint / len;
  let rise = dot(look, uniforms.airVeilEyeUp);
  let lookLevel = look - uniforms.airVeilEyeUp * rise;
  let ll = dot(lookLevel, lookLevel);
  var facing: f32 = 0.0;
  if (ll > 1e-8) { facing = dot(lookLevel, uniforms.airVeilSunLevel) * inverseSqrt(ll); }
  let hazeColor = mix(mix(uniforms.airVeilHazeAway, uniforms.airVeilHazeToward, 0.5 + 0.5 * facing), uniforms.airVeilHazeZenith, clamp(rise, 0.0, 1.0));
  var veil = (wf * uniforms.airVeilFogColor + wh * hazeColor) / max(wf + wh, 1e-6);
  if (linearSpace > 0.5) { veil = pow(veil, vec3f(2.2)); }
  return mix(veil, c, seenFog * seenHaze);
}
#endif
`;

export interface AirVeilCode {
  /** In the vertex shader: the fog's patches, for each vertex. */
  vertexDefinitions: string;
  /** At the end of the vertex shader, where the world position is `worldPos`. */
  vertexEnd: string;
  definitions: string;
  /** In a physically based material, on its composed colour (linear light) before its fog. */
  pbr: string;
  /** In a standard material, on its colour (as shown) before its fog. */
  standard: string;
}

/** The veil's code for a material: WGSL on WebGPU, GLSL elsewhere. */
export function selectAirVeilCode(engineKind?: string): AirVeilCode {
  if (engineKind === 'webgpu') {
    return {
      vertexDefinitions: VEIL_VERTEX_WGSL,
      vertexEnd: `#ifdef AIRVEIL
vertexOutputs.vAirVeilWet = airVeilWet(worldPos.xyz);
#endif
`,
      definitions: VEIL_DEFINITIONS_WGSL,
      pbr: `#ifdef AIRVEIL
finalColor = vec4f(airVeil(finalColor.rgb, fragmentInputs.vPositionW, fragmentInputs.vAirVeilWet, 1.0), finalColor.a);
#endif
`,
      standard: `#ifdef AIRVEIL
color = vec4f(airVeil(color.rgb, fragmentInputs.vPositionW, fragmentInputs.vAirVeilWet, 0.0), color.a);
#endif
`,
    };
  }
  return {
    vertexDefinitions: VEIL_VERTEX_GLSL,
    vertexEnd: `#ifdef AIRVEIL
vAirVeilWet = airVeilWet(worldPos.xyz);
#endif
`,
    definitions: VEIL_DEFINITIONS_GLSL,
    pbr: `#ifdef AIRVEIL
finalColor.rgb = airVeil(finalColor.rgb, vPositionW, vAirVeilWet, 1.0);
#endif
`,
    standard: `#ifdef AIRVEIL
color.rgb = airVeil(color.rgb, vPositionW, vAirVeilWet, 0.0);
#endif
`,
  };
}

const VEIL_PLUGIN = 'AirVeil';

type V3 = [number, number, number];

/** What the veil takes the same for every point it draws, made once a frame: the eye's altitude and up, the sun's direction, and the sun's bearing level with the eye's ground (none with the sun straight up or down). */
export interface AirVeilTerms {
  eyeAltitude: number;
  eyeUp: V3;
  sun: V3;
  sunLevel: V3;
}

export function airVeilTerms(eye: V3, centre: V3, radius: number, sun: V3): AirVeilTerms {
  const o: V3 = [eye[0] - centre[0], eye[1] - centre[1], eye[2] - centre[2]];
  const r = Math.hypot(...o);
  const eyeUp: V3 = [o[0] / r, o[1] / r, o[2] / r];
  const sl = Math.hypot(...sun);
  const s: V3 = [sun[0] / sl, sun[1] / sl, sun[2] / sl];
  const along = s[0] * eyeUp[0] + s[1] * eyeUp[1] + s[2] * eyeUp[2];
  const level: V3 = [s[0] - eyeUp[0] * along, s[1] - eyeUp[1] * along, s[2] - eyeUp[2] * along];
  const ll = level[0] * level[0] + level[1] * level[1] + level[2] * level[2];
  const sunLevel: V3 = ll > 1e-8 ? [level[0] / Math.sqrt(ll), level[1] / Math.sqrt(ll), level[2] / Math.sqrt(ll)] : [0, 0, 0];
  return { eyeAltitude: r - radius, eyeUp, sun: s, sunLevel };
}

class AirVeilPlugin extends MaterialPluginBase {
  private _isEnabled = true;

  constructor(
    material: ConstructorParameters<typeof MaterialPluginBase>[0],
    private frame: { current: AirVeilFrame | null; terms: AirVeilTerms | null },
  ) {
    super(material, VEIL_PLUGIN, 310, { AIRVEIL: false }, true, true);
  }

  /** Veils from another planet's air from now on (awayMaterials.ts). */
  rebind(frame: { current: AirVeilFrame | null; terms: AirVeilTerms | null }): void {
    this.frame = frame;
  }

  /** Read from the base's material: the plugin manager asks for the code inside the base's constructor, before this class's fields are set. */
  private get pbr(): boolean {
    return this._material.getClassName() === 'PBRMaterial';
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'AirVeilPlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0]): void {
    (defines as unknown as Record<string, boolean>)['AIRVEIL'] = this._isEnabled;
  }

  override getUniforms(shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL) {
    return {
      ubo: [
        { name: 'airVeilEye', size: 3, type: 'vec3' },
        { name: 'airVeilCentre', size: 3, type: 'vec3' },
        { name: 'airVeilToPlanet', size: 16, type: 'mat4' },
        { name: 'airVeilSun', size: 3, type: 'vec3' },
        { name: 'airVeilRadius', size: 1, type: 'float' },
        { name: 'airVeilFogDensity', size: 1, type: 'float' },
        { name: 'airVeilFogHeight', size: 1, type: 'float' },
        { name: 'airVeilFogColor', size: 3, type: 'vec3' },
        { name: 'airVeilPatchiness', size: 1, type: 'float' },
        { name: 'airVeilPatchSize', size: 1, type: 'float' },
        { name: 'airVeilHazeBeta', size: 1, type: 'float' },
        { name: 'airVeilHazeHeight', size: 1, type: 'float' },
        { name: 'airVeilHazeToward', size: 3, type: 'vec3' },
        { name: 'airVeilHazeAway', size: 3, type: 'vec3' },
        { name: 'airVeilHazeZenith', size: 3, type: 'vec3' },
        { name: 'airVeilFogFloor', size: 1, type: 'float' },
        { name: 'airVeilEyeAltitude', size: 1, type: 'float' },
        { name: 'airVeilEyeUp', size: 3, type: 'vec3' },
        { name: 'airVeilSunLevel', size: 3, type: 'vec3' },
      ],
      vertex: shaderLanguage === ShaderLanguage.WGSL ? VEIL_UNIFORMS_WGSL : VEIL_UNIFORMS_GLSL,
      fragment: shaderLanguage === ShaderLanguage.WGSL ? VEIL_UNIFORMS_WGSL : VEIL_UNIFORMS_GLSL,
    };
  }

  override bindForSubMesh(ubo: UniformBuffer): void {
    const v = this.frame.current;
    const t = this.frame.terms;
    if (!this._isEnabled || !v || !t) return;
    ubo.updateFloat3('airVeilEye', v.eye.x, v.eye.y, v.eye.z);
    ubo.updateFloat3('airVeilCentre', v.centre.x, v.centre.y, v.centre.z);
    ubo.updateMatrix('airVeilToPlanet', v.toPlanet);
    ubo.updateFloat3('airVeilSun', t.sun[0], t.sun[1], t.sun[2]);
    ubo.updateFloat('airVeilRadius', v.fog.radius);
    ubo.updateFloat('airVeilFogDensity', v.fog.density);
    ubo.updateFloat('airVeilFogHeight', v.fog.height);
    ubo.updateFloat3('airVeilFogColor', v.fogLight[0], v.fogLight[1], v.fogLight[2]);
    ubo.updateFloat('airVeilPatchiness', v.fog.patchiness);
    ubo.updateFloat('airVeilPatchSize', v.fog.patchSize);
    ubo.updateFloat('airVeilHazeBeta', v.hazeBeta);
    ubo.updateFloat('airVeilHazeHeight', v.hazeHeight);
    ubo.updateFloat3('airVeilHazeToward', v.hazeToward[0], v.hazeToward[1], v.hazeToward[2]);
    ubo.updateFloat3('airVeilHazeAway', v.hazeAway[0], v.hazeAway[1], v.hazeAway[2]);
    ubo.updateFloat3('airVeilHazeZenith', v.hazeZenith[0], v.hazeZenith[1], v.hazeZenith[2]);
    ubo.updateFloat('airVeilFogFloor', v.fog.floor);
    ubo.updateFloat('airVeilEyeAltitude', t.eyeAltitude);
    ubo.updateFloat3('airVeilEyeUp', t.eyeUp[0], t.eyeUp[1], t.eyeUp[2]);
    ubo.updateFloat3('airVeilSunLevel', t.sunLevel[0], t.sunLevel[1], t.sunLevel[2]);
  }

  override getCustomCode(shaderType: string, shaderLanguage: ShaderLanguage = ShaderLanguage.GLSL): { [pointName: string]: string } | null {
    const code = selectAirVeilCode(shaderLanguage === ShaderLanguage.WGSL ? 'webgpu' : 'webgl2');
    // Both kinds of material end their vertex shader with the world position in `worldPos`.
    if (shaderType === 'vertex') return { CUSTOM_VERTEX_DEFINITIONS: code.vertexDefinitions, CUSTOM_VERTEX_MAIN_END: code.vertexEnd };
    if (shaderType !== 'fragment') return null;
    // Both kinds of material have a point named for fog, where their colour is `finalColor` and `color` respectively.
    return { CUSTOM_FRAGMENT_DEFINITIONS: code.definitions, CUSTOM_FRAGMENT_BEFORE_FOG: this.pbr ? code.pbr : code.standard };
  }
}

/**
 * Veil every lit material in the scene, and every one added later (from the
 * next `update`), with the haze and fog along the eye's line to each point
 * it draws. `dispose` turns the veil off on them all and adds it to no more.
 */
export function createAirVeil(scene: Scene, _a: Atmosphere, _opts: { engineKind?: string }): AirVeilHandle {
  const frame: { current: AirVeilFrame | null; terms: AirVeilTerms | null } = { current: null, terms: null };
  const plugins: AirVeilPlugin[] = [];
  const arrivals = materialArrivals(scene);
  const attachAll = () =>
    arrivals.take((m) => {
      const kind = m.getClassName();
      if (kind !== 'StandardMaterial' && kind !== 'PBRMaterial') return;
      // A planet's ground that holds no one yet: taken once it does.
      if (isAway(m)) return false;
      const p = takePlugin(m, VEIL_PLUGIN, frame, () => new AirVeilPlugin(m, frame));
      if (p) plugins.push(p);
    });
  attachAll();
  let stopped = false;
  return {
    update(v) {
      if (stopped) return;
      attachAll();
      frame.current = v;
      frame.terms = airVeilTerms([v.eye.x, v.eye.y, v.eye.z], [v.centre.x, v.centre.y, v.centre.z], v.fog.radius, [v.sun.x, v.sun.y, v.sun.z]);
    },
    dispose() {
      stopped = true;
      arrivals.dispose();
      for (const p of plugins) p.isEnabled = false;
      plugins.length = 0;
    },
  };
}
