/**
 * The sky as a small picture around the eye, so the sky's shader looks it
 * up instead of summing the air's light for every pixel.
 *
 * Seen from one place, with the sun in one place, the air's light depends
 * only on how far the view is from straight up and how far round it is from
 * the sun's bearing, and is the same either side of the sun. The picture
 * keeps those two angles: across, the bearing from the sun's (0) to away
 * from it (1); down, from straight up (0) to the horizon (one half) to
 * straight down (1). Both are spaced unevenly, finest toward the sun and
 * about the horizon, where the light changes fastest (after Hillaire, "A
 * Scalable and Production Ready Sky and Atmosphere Rendering Technique",
 * 2020). The light let through to space along a view depends on the angle
 * from straight up alone; it is kept in the picture's last two columns.
 *
 * Drawn again every frame by the atmosphere's chunk from the same sums as
 * the reference (atmosphere.ts `skyLight`); this module is that picture made
 * on the processor, so the look-up is tested against the reference.
 */
import { skyLight, sunGlow, type Atmosphere, type Vec3 } from './atmosphere';

/** Texels across (bearings, plus the two columns of the light let through) and down (angles from straight up). */
export const SKY_VIEW_BEARINGS = 96;
export const SKY_VIEW_WIDTH = SKY_VIEW_BEARINGS + 2;
export const SKY_VIEW_HEIGHT = 128;

/** The eye's frame for the picture: straight up, the sun's bearing level with the ground and the bearing across it, and the angles from straight up to the horizon and from there to straight down. */
export interface SkyViewFrame {
  up: Vec3;
  forward: Vec3;
  side: Vec3;
  /** Radians from straight up to the horizon. */
  horizon: number;
  /** Radians from the horizon to straight down. */
  below: number;
}

const dot = (u: Vec3, v: Vec3) => u[0] * v[0] + u[1] * v[1] + u[2] * v[2];
const unit = (v: Vec3): Vec3 => {
  const l = Math.hypot(v[0], v[1], v[2]);
  return [v[0] / l, v[1] / l, v[2] / l];
};
const cross = (u: Vec3, v: Vec3): Vec3 => [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];

/** The frame of an eye at `origin` (metres from the planet's centre) with the sun along unit `sun`. */
export function skyViewFrame(a: Atmosphere, origin: Vec3, sun: Vec3): SkyViewFrame {
  const r = Math.hypot(origin[0], origin[1], origin[2]);
  const up = unit(origin);
  let flat: Vec3 = [sun[0] - up[0] * dot(sun, up), sun[1] - up[1] * dot(sun, up), sun[2] - up[2] * dot(sun, up)];
  // With the sun straight up or down every bearing is the same: any one will do.
  if (Math.hypot(...flat) < 1e-6) flat = Math.abs(up[0]) < 0.9 ? cross(up, [1, 0, 0]) : cross(up, [0, 0, 1]);
  const forward = unit(flat);
  const side = cross(up, forward);
  // The horizon is where a line from the eye grazes the ground's sphere; from inside it, level.
  const below = Math.acos(Math.min(1, Math.sqrt(Math.max(0, r * r - a.radius * a.radius)) / r));
  return { up, forward, side, horizon: Math.PI - below, below };
}

/** Where the unit direction `dir` lies in the picture, each 0 to 1: across (bearing) and down (angle from straight up). */
export function skyViewUnit(f: SkyViewFrame, dir: Vec3): [number, number] {
  const cz = Math.min(1, Math.max(-1, dot(dir, f.up)));
  const z = Math.acos(cz);
  const flat: Vec3 = [dir[0] - f.up[0] * cz, dir[1] - f.up[1] * cz, dir[2] - f.up[2] * cz];
  const fl = Math.hypot(...flat);
  const ca = fl > 1e-6 ? Math.min(1, Math.max(-1, dot(flat, f.forward) / fl)) : 1;
  const u = Math.sqrt(Math.max(0, 0.5 - 0.5 * ca));
  const v = z < f.horizon ? 0.5 * (1 - Math.sqrt(Math.max(0, 1 - z / f.horizon))) : 0.5 + 0.5 * Math.sqrt(Math.min(1, (z - f.horizon) / f.below));
  return [u, v];
}

/** The direction at a place in the picture (`skyViewUnit` undone), on the side of the sun's bearing that `side` points to. */
export function skyViewDirection(f: SkyViewFrame, u: number, v: number): Vec3 {
  const ca = 1 - 2 * u * u;
  const sa = Math.sqrt(Math.max(0, 1 - ca * ca));
  const z = v < 0.5 ? f.horizon * (1 - (1 - 2 * v) ** 2) : f.horizon + f.below * (2 * v - 1) ** 2;
  const cz = Math.cos(z), sz = Math.sin(z);
  return [0, 1, 2].map((k) => f.up[k]! * cz + sz * (f.forward[k]! * ca + f.side[k]! * sa)) as Vec3;
}

/** The picture, as the chunk draws it: red, green, blue for each texel, row by row from straight up. */
export interface SkyViewPicture {
  frame: SkyViewFrame;
  texels: Float32Array;
}

/** Make the picture on the processor: each bearing texel the air's light toward its direction, and each of the last two columns the light let through. */
export function bakeSkyView(a: Atmosphere, origin: Vec3, sun: Vec3, steps: number, lightSteps: number): SkyViewPicture {
  const frame = skyViewFrame(a, origin, sun);
  const texels = new Float32Array(SKY_VIEW_WIDTH * SKY_VIEW_HEIGHT * 3);
  for (let j = 0; j < SKY_VIEW_HEIGHT; j++) {
    const v = j / (SKY_VIEW_HEIGHT - 1);
    for (let i = 0; i < SKY_VIEW_WIDTH; i++) {
      const through = i >= SKY_VIEW_BEARINGS;
      const dir = skyViewDirection(frame, through ? 0 : i / (SKY_VIEW_BEARINGS - 1), v);
      const l = skyLight(a, origin, dir, sun, steps, lightSteps);
      texels.set(through ? l.through : l.scatter, (j * SKY_VIEW_WIDTH + i) * 3);
    }
  }
  return { frame, texels };
}

/** The picture read as a graphics card's filtered look-up reads it: between the four nearest texels, at texel column `x` and row `y`. */
function lookUp(p: SkyViewPicture, x: number, y: number): Vec3 {
  const x0 = Math.floor(x), y0 = Math.floor(y);
  const fx = x - x0, fy = y - y0;
  const at = (i: number, j: number, k: number) => {
    const ii = Math.min(SKY_VIEW_WIDTH - 1, Math.max(0, i)), jj = Math.min(SKY_VIEW_HEIGHT - 1, Math.max(0, j));
    return p.texels[(jj * SKY_VIEW_WIDTH + ii) * 3 + k]!;
  };
  return [0, 1, 2].map((k) => (at(x0, y0, k) * (1 - fx) + at(x0 + 1, y0, k) * fx) * (1 - fy) + (at(x0, y0 + 1, k) * (1 - fx) + at(x0 + 1, y0 + 1, k) * fx) * fy) as Vec3;
}

/** The air's light toward unit `dir`, read from the picture. */
export function sampleSkyView(p: SkyViewPicture, dir: Vec3): { scatter: Vec3; through: Vec3 } {
  const [u, v] = skyViewUnit(p.frame, dir);
  const y = v * (SKY_VIEW_HEIGHT - 1);
  return { scatter: lookUp(p, u * (SKY_VIEW_BEARINGS - 1), y), through: lookUp(p, SKY_VIEW_BEARINGS + 1, y) };
}

/** The sky's colour toward `dir` as the shader draws it from the picture: the air's light, the sun in its glow through the air, tone-mapped. */
export function skyViewColour(p: SkyViewPicture, dir: Vec3, sun: Vec3): Vec3 {
  const { scatter, through } = sampleSkyView(p, dir);
  const g = sunGlow(dot(dir, sun));
  return [0, 1, 2].map((k) => 1 - Math.exp(-(scatter[k]! + g * through[k]!))) as Vec3;
}
